 "content": "def transform(grid):
    """Copy the 3x4 six-cell motif, recoloring every matching motif to its marker color."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    marker_colors = [v for row in grid for v in row if v not in (0, 1)]
    if not marker_colors:
        return out
    color = marker_colors[0]
    motif = {(0, 0), (0, 1), (1, 0), (1, 2), (1, 3), (2, 0)}
    for r in range(h - 2):
        for c in range(w - 3):
            if all(grid[r + dr][c + dc] == 1 for dr, dc in motif):
                for dr, dc in motif:
                    out[r + dr][c + dc] = color
    return out
